mapper.select:
SELECT a.id, a.title, a.summary, a.cover_url, a.is_top, a.is_featured, a.published_at, c.name AS category_name, t.id AS tag_id, t.name AS tag_name FROM article a
JOIN article_tag filter_tag ON filter_tag.article_id = a.id AND filter_tag.tag_id = #{tagId}
LEFT JOIN category c ON c.id = a.category_id
LEFT JOIN article_tag art_tag ON art_tag.article_id = a.id
LEFT JOIN tag t ON t.id = art_tag.tag_id
WHERE a.is_deleted = 0 AND a.status = 1 ORDER BY a.is_top DESC, a.is_featured DESC, a.published_at DESC, a.id DESC LIMIT #{offset}, #{size}
